// Turn a portal or website enquiry e-mail into one clean lead.
// Knows Rightmove, Zoopla, OnTheMarket, Zillow, Realtor.com, Homes.com, Trulia, Redfin, OpenRent; anything else is read as a plain enquiry.
const PORTALS = [['rightmove', 'Rightmove'], ['zoopla', 'Zoopla'], ['onthemarket', 'OnTheMarket'], ['zillow', 'Zillow'],
  ['realtor.com', 'Realtor.com'], ['homes.com', 'Homes.com'], ['trulia', 'Trulia'], ['redfin', 'Redfin'], ['openrent', 'OpenRent']];
const isSystem = e => PORTALS.some(([k]) => e.includes(k)) || /no-?reply|donotreply|notifications?@|mailer-daemon/.test(e);
return $input.all().map(item => {
  const m = item.json;
  const fromAddr = String(m.from?.value?.[0]?.address || m.from?.text || m.From || '').toLowerCase();
  const fromName = m.from?.value?.[0]?.name || '';
  const replyTo = String(m.replyTo?.value?.[0]?.address || '').toLowerCase();
  const html = m.html || m.textAsHtml || '';
  const text = String(m.text || html.replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|tr|li|h\d)>/gi, '\n').replace(/<[^>]+>/g, ' ') || m.snippet || '')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/[ \t]+/g, ' ').replace(/\r/g, '');
  const subject = m.subject || m.Subject || '';
  const hay = (fromAddr + ' ' + subject + ' ' + text.slice(0, 4000)).toLowerCase();
  const portal = (PORTALS.find(([k]) => fromAddr.includes(k)) || PORTALS.find(([k]) => hay.includes(k + '.')) || [null, 'Email'])[1];
  const field = (...labels) => {
    for (const l of labels) {
      const x = text.match(new RegExp('(?:^|\\n)\\s*(?:' + l + ')\\s*[:\\-]\\s*([^\\n]+)', 'i'));
      if (x && x[1].trim()) return x[1].trim();
    }
    return '';
  };
  const all = (text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || []).map(e => e.toLowerCase());
  let email = (field('e-?mail(?: address)?', 'email') .match(/[^\s<>()]+@[^\s<>()]+\.[a-z]{2,}/i) || [''])[0].toLowerCase();
  if (!email && replyTo && !isSystem(replyTo)) email = replyTo;
  if (!email) email = all.find(e => !isSystem(e) && e !== fromAddr) || '';
  if (!email && portal === 'Email' && !isSystem(fromAddr)) email = fromAddr;
  const name = field('name', 'full name', 'your name', 'contact name', 'customer name', 'buyer name')
    || [field('first name'), field('last name|surname')].filter(Boolean).join(' ') || (portal === 'Email' ? fromName : '');
  const phone = field('phone(?: number)?', 'telephone', 'tel', 'mobile', 'contact number').replace(/[^+0-9() -]/g, '').trim();
  let message = field('message', 'comments?', 'enquiry', 'inquiry', 'additional (?:information|comments)', 'questions?');
  if (message.length < 25) message = (message ? message + ' | ' : '') + text.replace(/\s+/g, ' ').slice(0, 1200);
  const ref = field('property ref(?:erence)?', 'listing (?:id|ref|number)', 'mls ?#?', 'property id', 'ref(?:erence)?(?: number)?');
  const address = field('property(?: address)?', 'address', 'listing', 'home address')
    || ((subject.match(/(?:enquiry|inquiry|interest|request|lead)(?: about| for| on| re|:)\s*(.+)$/i) || [])[1] || '');
  const type = /valuation|value my|appraisal|sell my|selling my|market appraisal/i.test(hay) ? 'valuation'
    : /viewing|showing|tour|\bview\b|arrange a visit/i.test(hay) ? 'viewing'
    : /to let|to rent|rental|tenan|letting|pcm|per month/i.test(hay) ? 'rental' : 'general';
  return { json: { source: portal, received_at: $now.toFormat('yyyy-MM-dd HH:mm'), name: name.slice(0, 80), email, phone,
    message: message.slice(0, 1500), property_ref: ref.slice(0, 40), property_address: address.slice(0, 160),
    listed_price: field('price', 'asking price', 'list price'), budget_given: field('budget', 'max(?:imum)? budget', 'price range'),
    timeline_given: field('timeline', 'moving date', 'move date', 'when'), enquiry_type: type, subject,
    gmail_message_id: m.id || '', gmail_thread_id: m.threadId || '' } };
});

// Map common website-form field names (Contact Form 7, Elementor, Webflow, Typeform-style) to lead fields
return $input.all().map(item => {
  const b = item.json.body && typeof item.json.body === 'object' ? item.json.body : item.json;
  const g = (...k) => { for (const x of k) { const v = b[x]; if (v !== undefined && v !== null && String(v).trim()) return String(v).trim(); } return ''; };
  const name = g('name', 'full_name', 'fullName', 'your-name', 'Name') || [g('first_name', 'firstName', 'fname'), g('last_name', 'lastName', 'lname')].filter(Boolean).join(' ');
  const message = g('message', 'comments', 'enquiry', 'inquiry', 'your-message', 'notes', 'Message');
  const t = (message + ' ' + g('type', 'enquiry_type')).toLowerCase();
  return { json: { source: g('source') || 'Website', received_at: $now.toFormat('yyyy-MM-dd HH:mm'), name: name.slice(0, 80),
    email: g('email', 'your-email', 'email_address', 'Email').toLowerCase(), phone: g('phone', 'tel', 'telephone', 'mobile', 'your-phone', 'Phone'),
    message: message.slice(0, 1500), property_ref: g('property_ref', 'listing_id', 'ref', 'property_id', 'mls'),
    property_address: g('property', 'property_address', 'listing', 'address'), listed_price: g('price'),
    budget_given: g('budget', 'max_budget', 'price_range'), timeline_given: g('timeline', 'move_date', 'when'),
    enquiry_type: g('type', 'enquiry_type') || (/valuation|sell my|appraisal/.test(t) ? 'valuation' : /viewing|showing|tour/.test(t) ? 'viewing' : /rent|let/.test(t) ? 'rental' : 'general'),
    subject: '', gmail_message_id: '', gmail_thread_id: '' } };
});

