const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Blend the AI read-out with simple rules -> final score, temperature, next follow-up date and the CRM row
const s = $('Set responder settings').first().json;
const days = String(s.followup_days || '1,3,7').split(',').map(Number).filter(n => n > 0);
const hot = Number(s.hot_score) || 70;
const src = $('Set responder settings').all();
const mode = String(s.reply_mode || 'draft').toLowerCase() === 'send' ? 'send' : 'draft';
return $input.all().map((item, i) => {
  const l = src[i].json, o = item.json.output || {};
  const why = [];
  let pts = 0;
  if (o.pre_approved === 'yes') { pts += 15; why.push('pre-approved / funds ready'); }
  const tmRaw = o.timeline_months === null || o.timeline_months === '' || o.timeline_months === undefined ? null : Number(o.timeline_months);
  const tm = Number.isFinite(tmRaw) && !/^unknown$/i.test(String(o.timeline || '').trim()) ? tmRaw : null;  // ignore a number the model filled in for an unknown timeline
  if (tm !== null && tm <= 3) { pts += 10; why.push('moving within 3 months'); } else if (tm !== null && tm > 12) pts -= 10;
  if (o.intent === 'sell_valuation' || l.enquiry_type === 'valuation') { pts += 10; why.push('valuation request'); }
  if (l.phone) { pts += 5; why.push('left a phone number'); }
  const bmax = Number(o.budget_max) || 0, price = Number(l.property_price) || 0;
  if (bmax && price && bmax >= 0.9 * price) { pts += 5; why.push('budget fits the price'); }
  if (bmax && price && bmax < 0.75 * price) { pts -= 15; why.push('budget well below the price'); }
  if (l.is_repeat) { pts += 5; why.push('repeat enquiry'); }
  const score = Math.max(0, Math.min(100, Math.round(0.6 * (Number(o.ai_score) || 0) + pts)));
  const temperature = score >= hot ? 'hot' : score >= 40 ? 'warm' : 'cold';
  const canReply = !!l.email && !l.is_repeat;
  const reply_status = !l.email ? 'no e-mail: call them' : l.is_repeat ? 'repeat enquiry: agent to reply' : mode === 'send' ? 'sent' : 'draft in Gmail';
  const row = {
    lead_id: l.lead_id, created_at: l.created_at || l.received_at, updated_at: $now.toFormat('yyyy-MM-dd HH:mm'), source: l.source,
    name: l.name, email: l.email, phone: l.phone, enquiry_type: l.enquiry_type, intent: o.intent || '',
    property: l.property_matched || l.property_address || l.property_ref || '', budget: o.budget || l.budget_given || '',
    timeline: o.timeline || l.timeline_given || '', pre_approved: o.pre_approved || 'unknown', position: o.position || 'unknown',
    score, temperature, score_reasons: why.join('; '), summary: o.summary || '', missing_info: (o.missing_info || []).join('; '),
    stage: l.is_repeat ? (l.previous_stage || 'contacted') : canReply ? 'contacted' : 'call needed', status: 'active',
    reply_status, followups_sent: Number(l.followups_sent) || 0,
    next_followup: canReply && days.length ? $today.plus({ days: days[0] }).toFormat('yyyy-MM-dd') : '',
    last_contact: new Date().toISOString(), enquiries: (Number(l.previous_enquiries) || 0) + 1, message: l.message,
    reply_subject: o.reply_subject || 'Your enquiry', reply_body: o.reply_body || '',
  };
  const icon = temperature === 'hot' ? '🔥' : '🏠';
  const alert_html = `${icon} <b>${esc(temperature.toUpperCase())} lead (${score}/100)</b>: ${esc(l.name || 'unknown')}\n`
    + `${esc(row.intent)} · ${esc(row.property || 'no property given')}\nBudget: ${esc(row.budget || '?')} · Timeline: ${esc(row.timeline || '?')} · Pre-approved: ${esc(row.pre_approved)}\n`
    + `📞 ${esc(l.phone || '-')} · ✉️ ${esc(l.email || '-')}\n${esc(row.summary)}\nWhy: ${esc(row.score_reasons || '-')}\nReply: ${esc(reply_status)}`;
  return { json: { ...row, can_reply: canReply, reply_mode: mode, alert_html } };
});
